const moduleBaseUrl = "https://framer.com/m/phosphor-icons/"

/*
 ** ICON
 */

type IconWeight = "thin" | "light" | "regular" | "bold" | "fill" | "duotone"

export interface IconProps {
    mirrored?: boolean
    width?: number
    height?: number
    color?: string
    weight?: IconWeight
    selectByList?: boolean
    iconSearch?: string
    iconSelection?: (typeof iconKeys)[number]
    onTap?: any
    onClick?: any
    onMouseEnter?: any
    onMouseLeave?: any
    onMouseDown?: any
    onMouseUp?: any
}

const weightOptions: IconWeight[] = [
    "thin",
    "light",
    "regular",
    "bold",
    "fill",
    "duotone",
]

const lowercaseIconKeyPairs = iconKeys.reduce((res, key) => {
    res[key.toLowerCase()] = key
    return res
}, {})

/**
 * PHOSPHOR
 *
 * @framerSupportedLayoutWidth fixed
 * @framerSupportedLayoutHeight fixed
 *
 * @framerIntrinsicWidth 24
 * @framerIntrinsicHeight 24
 */
export function Icon(props: IconProps) {
    const {
        color,
        selectByList,
        iconSearch,
        iconSelection,
        onClick,
        onMouseDown,
        onMouseUp,
        onMouseEnter,
        onMouseLeave,
        weight,
        mirrored,
    } = props

    const isMounted = useRef(false)

    const iconKey = useIconSelection<any>(
        iconKeys,
        selectByList,
        iconSearch,
        iconSelection,
        lowercaseIconKeyPairs
    )

    const [SelectedIcon, setSelectedIcon] = useState(
        iconKey === "Home" ? HouseFactory(React) : null
    )

    async function importModule() {
        // Get the selected module
        try {
            const version = "0.0.57"
            const iconModuleUrl = `${moduleBaseUrl}${iconKey}.js@${version}`
            const module = await import(/* webpackIgnore: true */ iconModuleUrl)
            if (isMounted.current) setSelectedIcon(module.default(React))
        } catch (err) {
            if (isMounted.current) setSelectedIcon(null)
        }
    }

    useEffect(() => {
        isMounted.current = true
        importModule()
        return () => {
            isMounted.current = false
        }
    }, [iconKey])

    const isOnCanvas = RenderTarget.current() === RenderTarget.canvas
    const emptyState = isOnCanvas ? <NullState /> : null

    return (
        <motion.div
            style={{ display: "contents" }}
            {...{ onClick, onMouseEnter, onMouseLeave, onMouseDown, onMouseUp }}
        >
            {SelectedIcon ? (
                <svg
                    xmlns="http://www.w3.org/2000/svg"
                    viewBox="0 0 256 256"
                    style={{
                        userSelect: "none",
                        width: "100%",
                        height: "100%",
                        display: "inline-block",
                        fill: color,
                        color,
                        flexShrink: 0,
                        transform: mirrored ? "scale(-1, 1)" : undefined,
                    }}
                    focusable="false"
                    color={color}
                >
                    <SelectedIcon color={color} weight={weight} />
                </svg>
            ) : (
                emptyState
            )}
        </motion.div>
    )
}

Icon.displayName = "Phosphor"

Icon.defaultProps = {
    width: 24,
    height: 24,
    iconSelection: "House" as (typeof iconKeys)[number],
    iconSearch: "House",
    color: "#66F",
    selectByList: true,
    weight: "regular" as IconWeight,
    mirrored: false,
}

addPropertyControls(Icon, {
    selectByList: {
        type: ControlType.Boolean,
        title: "Select",
        enabledTitle: "List",
        disabledTitle: "Search",
        defaultValue: Icon.defaultProps.selectByList,
    },
    iconSelection: {
        type: ControlType.Enum,
        options: iconKeys,
        defaultValue: Icon.defaultProps.iconSelection,
        title: "Name",
        hidden: ({ selectByList }) => !selectByList,
        description:
            "Find every icon name on the [Phosphor site](https://phosphoricons.com/)",
    },
    iconSearch: {
        type: ControlType.String,
        title: "Name",
        placeholder: "Menu, Wifi, Box…",
        hidden: ({ selectByList }) => selectByList,
    },
    color: {
        type: ControlType.Color,
        title: "Color",
        defaultValue: Icon.defaultProps.color,
    },
    weight: {
        type: ControlType.Enum,
        title: "Weight",
        optionTitles: weightOptions.map(
            (piece) => piece.charAt(0).toUpperCase() + piece.slice(1)
        ),
        options: weightOptions,
        defaultValue: Icon.defaultProps.weight,
    },
    mirrored: {
        type: ControlType.Boolean,
        enabledTitle: "Yes",
        disabledTitle: "No",
        defaultValue: Icon.defaultProps.mirrored,
    },

    ...defaultEvents,
})
